INSERT OR IGNORE INTO notices (id,title,body,level,pinned,created_at,expires_at) VALUES (1,'9友地图上线了','在荒原纸面上撑一把伞，看看同服的司辰都散落在哪些城市。
· 注册时请如实选择渠道服——不同渠道服在游戏里加不了好友。
· 坐标会模糊到约 500 米再展示，请不要把伞放在住处或学校。
· 觉得哪里不好看、哪里不好用，都欢迎告诉站长。','info',1,'2026-11-19T11:41:11.585Z',NULL);
INSERT OR IGNORE INTO notices (id,title,body,level,pinned,created_at,expires_at) VALUES (2,'关于位置与隐私','位置属于敏感个人信息，需要你单独同意才会展示，随时可以在「手提箱 → 隐私」里关掉。
地图上所有坐标都是模糊后的结果，任何人（包括站长）都看不到你的精确位置。','warn',0,'2026-11-19T11:41:11.587Z',NULL);
INSERT OR IGNORE INTO notices (id,title,body,level,pinned,created_at,expires_at) VALUES (3,'示例公告：可以删掉这条','发布新公告：node scripts/notice.mjs "标题" "正文" --level warn --pin
或配置 ADMIN_TOKEN 后调用 POST /api/admin/notices。','info',0,'2026-11-19T11:41:11.588Z',NULL);
